// Server-side validation: never trust what the browser sent.
const PRICES = { shoe: 50, hat: 20 }; // the server owns the real prices

function validateOrder(body) {
  const errors = [];
  if (!PRICES.hasOwnProperty(body.item)) errors.push("unknown item");
  // Number.isInteger rejects strings, decimals and NaN
  if (!Number.isInteger(body.qty) || body.qty < 1 || body.qty > 10) {
    errors.push("qty must be an integer 1..10");
  }
  return errors;
}

function handleOrder(body) {
  const errors = validateOrder(body);
  if (errors.length) return { status: 422, errors };
  // Ignore body.price completely: recompute on the server
  const total = PRICES[body.item] * body.qty;
  return { status: 201, total };
}

