// Simulate when each script type runs. Pure logic, no browser needed.
// Times are in ms. "ready" = when the download finishes.
const scripts = [
  { name: "classic", mode: "classic", ready: 30 },
  { name: "defer-A", mode: "defer", ready: 80 },
  { name: "defer-B", mode: "defer", ready: 20 },
  { name: "async-X", mode: "async", ready: 50 },
  { name: "module-M", mode: "defer", ready: 40 }, // modules behave like defer
];
const parseEnd = 100; // time the HTML parser would finish if nothing blocked it

const events = [];
let parserDelay = 0;
for (const s of scripts) {
  if (s.mode === "classic") {
    // parser stops, waits for download, then runs the script
    events.push({ t: s.ready, text: s.name + " runs (parser was blocked)" });
    parserDelay += 10;
  } else if (s.mode === "async") {
    // runs the moment it arrives, order not guaranteed
    events.push({ t: s.ready, text: s.name + " runs as soon as it arrives" });
  }
}
const parsed = parseEnd + parserDelay;
events.push({ t: parsed, text: "HTML parsing finished" });
// deferred scripts run in document order after parsing, even if B arrived first
let t = parsed;
for (const s of scripts.filter(x => x.mode === "defer")) {
  t += 1;
  events.push({ t, text: s.name + " runs (in document order)" });
}
events.push({ t: t + 1, text: "DOMContentLoaded fires" });
events.sort((a, b) => a.t - b.t);
events.forEach(e => console.log(String(e.t).padStart(4), "ms", e.text));

// A correct fetch wrapper. fakeFetch stands in for the real fetch.
async function fakeFetch(url) {
  if (url === "/missing") return { ok: false, status: 404, json: async () => ({ error: "not found" }) };
  if (url === "/offline") throw new TypeError("Failed to fetch"); // network failure
  return { ok: true, status: 200, json: async () => ({ id: 1 }) };
}

async function getJson(url) {
  let res;
  try {
    res = await fakeFetch(url);
  } catch (e) {
    // fetch rejects only when the request could not complete
    throw new Error("network error: " + e.message);
  }
  // HTTP errors still resolve, so we must check res.ok ourselves
  if (!res.ok) {
    const body = await res.json();
    const err = new Error("HTTP " + res.status);
    err.status = res.status;
    err.body = body;
    throw err;
  }
  return res.json();
}

async function main() {
  for (const url of ["/users/1", "/missing", "/offline"]) {
    try {
      console.log(url, "->", JSON.stringify(await getJson(url)));
    } catch (e) {
      console.log(url, "-> failed:", e.message, e.body ? JSON.stringify(e.body) : "");
    }
  }
  // Plain fake fetch on /missing does NOT throw: this is the trap
  const raw = await fakeFetch("/missing");
  console.log("raw fetch on 404 resolved, ok =", raw.ok);
}
main();

// Model of a browser cache: fresh, stale + 304 revalidation, or full download.
const cache = {}; // url -> { etag, storedAt, maxAge }
const server = {
  "/app.3f9a1c.js": { etag: '"a1"', maxAge: 31536000 },
  "/index.html":    { etag: '"h1"', maxAge: 0 }, // like no-cache: always revalidate
};

function request(url, now) {
  const c = cache[url];
  if (c && now - c.storedAt < c.maxAge) return "served from cache (fresh, no network)";
  const s = server[url];
  if (c && c.etag === s.etag) {
    c.storedAt = now; // 304 Not Modified: tiny response, body reused
    return "304 Not Modified (revalidated, no body)";
  }
  cache[url] = { etag: s.etag, storedAt: now, maxAge: s.maxAge };
  return "200 OK (full download)";
}

const steps = [
  [0, "/index.html"], [0, "/app.3f9a1c.js"],
  [60, "/index.html"], [60, "/app.3f9a1c.js"], // second visit one minute later
];
for (const [t, url] of steps) {
  console.log("t=" + t + "s", url, "->", request(url, t));
}
server["/index.html"].etag = '"h2"'; // new deploy changes the HTML
